-- seed_activities_profesional.sql (RF-34, dimension "Profesional") -- escrito a mano.
-- 10 actividades de apoyo mutuo en metas y trabajo (bienestar ocupacional; Swarbrick 2006,
-- National Wellness Institute). activity_type = CAREER -> IdeaCategory.PROFESIONAL.
-- Costos y duraciones aproximados (needs_review = 1) hasta el catalogo real (U12).
-- Requiere la tabla activities (add_kb_tables.sql). Idempotente: re-ejecutarlo actualiza.
-- SET NAMES: desde cmd el cliente de mysql leia el archivo en la pagina de codigos de Windows y los
-- acentos quedaban rotos ("com├║n"); asi se leen como UTF-8 sin importar desde donde se corra.

SET NAMES utf8mb4;

INSERT INTO `nexus`.`activities` (slug, title, activity_type, location_scope, place_types, dayparts, seasons, duration_min, duration_avg, duration_max, difficulty_physical, difficulty_mental, collaboration, preparation, requires_booking, equipment, cost_mxn_pp, price_band, is_outdoor, weather_ok, ambience, description, rationale, enriched_by, confidence, reviewed_by, needs_review) VALUES
  ('planear-metas-del-ano', 'Planear sus metas del año', 'CAREER', 'HOME', '', 'AFTERNOON|NIGHT', 'ANY', 90, 120, 180, 0, 3, 9, 2, 0, 'cartulina|revistas', 0, 'FREE', 0, 'ANY', 'HOME|QUIET', 'Armar juntos un tablero de visión con las metas personales y de trabajo de cada uno para este año.', 'Conocer y apoyar las metas del otro fortalece el bienestar profesional de los dos.', 'manual', 1.0, NULL, 1),
  ('tarde-de-coworking-en-cafeteria', 'Tarde de coworking en una cafetería', 'CAREER', 'CITY', 'CAFE', 'AFTERNOON|MORNING', 'ANY', 120, 180, 240, 0, 3, 5, 1, 0, 'laptop', 150, 'LOW', 0, 'ANY', 'QUIET|SOCIAL', 'Ir juntos a una cafetería a avanzar cada quien en su trabajo o proyecto, con pausas para platicar.', 'Acompañarse sin interrumpirse respeta el espacio de cada uno y hace más ligera la jornada.', 'manual', 1.0, NULL, 1),
  ('ensayar-entrevista-o-presentacion', 'Ensayar una entrevista o presentación', 'CAREER', 'HOME', '', 'AFTERNOON|NIGHT', 'ANY', 45, 60, 90, 0, 4, 8, 2, 0, '', 0, 'FREE', 0, 'ANY', 'HOME|QUIET', 'Uno practica una entrevista o exposición y el otro hace de entrevistador y le da retroalimentación.', 'Dar consejos y ánimo justo antes de un reto importante es una forma concreta de apoyo.', 'manual', 1.0, NULL, 1),
  ('cena-para-celebrar-un-logro', 'Cena para celebrar un logro', 'CAREER', 'CITY', 'RESTAURANT', 'NIGHT', 'ANY', 90, 120, 180, 0, 0, 6, 1, 1, '', 400, 'MID', 0, 'ANY', 'ROMANTIC|SOCIAL', 'Salir a cenar para festejar un ascenso, un examen aprobado o la entrega de un proyecto.', 'Reconocer los logros del otro refuerza la motivación y el orgullo compartido.', 'manual', 1.0, NULL, 1),
  ('asistir-a-una-charla-o-conferencia', 'Asistir a una charla o conferencia', 'CAREER', 'CITY', 'COMMUNITY_CENTRE|EVENTS_VENUE', 'AFTERNOON|NIGHT', 'ANY', 60, 120, 180, 0, 4, 4, 1, 0, '', 0, 'FREE', 0, 'ANY', 'CULTURAL|QUIET', 'Ir juntos a una plática o conferencia gratuita sobre un tema de su trabajo o de su interés.', 'Aprender algo nuevo en pareja da temas de conversación y abre ideas para sus carreras.', 'manual', 1.0, NULL, 1),
  ('curso-corto-en-pareja', 'Curso corto en pareja', 'CAREER', 'HOME', '', 'AFTERNOON|MORNING|NIGHT', 'ANY', 60, 120, 180, 0, 5, 7, 1, 0, 'laptop', 300, 'MID', 0, 'ANY', 'HOME|QUIET', 'Tomar juntos un curso corto en línea de finanzas personales, un idioma o una herramienta útil para el trabajo.', 'Desarrollar habilidades nuevas al mismo ritmo los motiva a seguir aprendiendo.', 'manual', 1.0, NULL, 1),
  ('organizar-juntos-las-finanzas-del-mes', 'Organizar juntos sus finanzas del mes', 'CAREER', 'HOME', '', 'AFTERNOON|NIGHT', 'ANY', 60, 90, 120, 0, 4, 8, 2, 0, 'hoja-de-calculo', 0, 'FREE', 0, 'ANY', 'HOME|QUIET', 'Revisar ingresos y gastos, y fijar una meta de ahorro para algo que quieran hacer juntos.', 'Hablar de dinero con calma reduce tensiones y alinea sus planes a futuro.', 'manual', 1.0, NULL, 1),
  ('arrancar-un-proyecto-juntos', 'Arrancar un proyecto juntos', 'CAREER', 'HOME', '', 'AFTERNOON|NIGHT', 'ANY', 90, 120, 240, 0, 4, 9, 2, 0, 'laptop', 0, 'FREE', 0, 'ANY', 'HOME|QUIET', 'Dar el primer paso de un proyecto en común: un blog, un pequeño negocio o el portafolio de alguno.', 'Construir algo propio entre los dos combina sus habilidades y les da una meta compartida.', 'manual', 1.0, NULL, 1),
  ('visitar-una-feria-de-emprendimiento-o-empleo', 'Visitar una feria de emprendimiento o de empleo', 'CAREER', 'CITY', 'EVENTS_VENUE|MARKET', 'AFTERNOON|MORNING', 'ANY', 120, 180, 240, 1, 2, 5, 1, 0, '', 0, 'FREE', 0, 'ANY', 'SOCIAL', 'Recorrer juntos una feria de emprendedores o de empleo para conocer opciones e ideas.', 'Explorar oportunidades en pareja ayuda a imaginar y apoyar el siguiente paso de cada uno.', 'manual', 1.0, NULL, 1),
  ('leer-un-libro-de-desarrollo-profesional', 'Leer un libro de desarrollo profesional y comentarlo', 'CAREER', 'HOME', '', 'AFTERNOON|NIGHT', 'ANY', 45, 60, 90, 0, 4, 6, 1, 0, 'libro', 250, 'MID', 0, 'ANY', 'HOME|QUIET', 'Leer cada quien unos capítulos de un libro sobre trabajo o hábitos y comentarlos juntos.', 'Compartir lo que aprenden les da ideas para apoyarse en sus metas.', 'manual', 1.0, NULL, 1)
ON DUPLICATE KEY UPDATE title = VALUES(title), activity_type = VALUES(activity_type), location_scope = VALUES(location_scope), place_types = VALUES(place_types), dayparts = VALUES(dayparts), duration_min = VALUES(duration_min), duration_avg = VALUES(duration_avg), duration_max = VALUES(duration_max), difficulty_physical = VALUES(difficulty_physical), difficulty_mental = VALUES(difficulty_mental), collaboration = VALUES(collaboration), preparation = VALUES(preparation), requires_booking = VALUES(requires_booking), equipment = VALUES(equipment), cost_mxn_pp = VALUES(cost_mxn_pp), price_band = VALUES(price_band), ambience = VALUES(ambience), description = VALUES(description), rationale = VALUES(rationale), enriched_by = VALUES(enriched_by), needs_review = VALUES(needs_review);

-- Comprobacion: 10 actividades de Profesional.
SELECT COUNT(*) AS profesional FROM `nexus`.`activities` WHERE activity_type = 'CAREER';
